Create Entry.code:
// Add a record to a library (e.g. a new beneficiary visit).
createEntry(
  // 1) Library id.
  $.data.libraryId,
  // 2) Entry body: one { id, value } per field (ids come from getFields).
  {
    fields: [
      { id: 1, value: $.data.beneficiaryName },
      { id: 2, value: $.data.visitDate },
      { id: 3, value: $.data.householdSize },
    ],
  }
);

Update Entry.code:
// Update fields on an existing entry.
updateEntry(
  // 1) Library id.
  $.data.libraryId,
  // 2) Entry id.
  $.data.entryId,
  // 3) Only the fields to change.
  {
    fields: [
      { id: 4, value: 'Follow-up completed' },
    ],
  }
);

List Entries.code:
// List entries in a library.
listEntries(
  // 1) Library id.
  $.data.libraryId,
  // 2) Options.
  {
    pageSize: 100,
    fields: 'all', // or a comma-separated list of field ids
  }
);

List Changed Entries.code:
// Fetch entries changed since the last sync.
listEntries($.data.libraryId, {
  // Revision saved from the previous run.
  startRevision: $.data.lastRevision,
});

Get Entry.code:
// Fetch one entry.
getEntry(
  // 1) Library id.
  $.data.libraryId,
  // 2) Entry id.
  $.data.entryId
);
